CREATE TABLE WEAVER_USER_ACCOUNT(id CHAR(36) CHARACTER SET ascii PRIMARY KEY,email VARCHAR(254) NOT NULL,display_name VARCHAR(80),verified_at DATETIME(6));
CREATE TABLE WEAVER_ACCOUNT_WORKSPACE(user_id CHAR(36) CHARACTER SET ascii PRIMARY KEY,owner_id CHAR(36) CHARACTER SET ascii NOT NULL,name VARCHAR(80),revision BIGINT DEFAULT 0,migrated BOOLEAN DEFAULT FALSE,archived_at DATETIME(6),purge_after DATETIME(6));
CREATE TABLE WEAVER_WORKSPACE_DELETION(workspace_id CHAR(36) CHARACTER SET ascii PRIMARY KEY);
CREATE TABLE WEAVER_WORKSPACE_MEMBER(workspace_id CHAR(36) CHARACTER SET ascii,user_id CHAR(36) CHARACTER SET ascii,role VARCHAR(16),joined_at DATETIME(6) DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(workspace_id,user_id));
CREATE TABLE WEAVER_WORKSPACE_ITEM(user_id CHAR(36) CHARACTER SET ascii,item_key CHAR(64),kind VARCHAR(64),payload_bytes BIGINT,deleted BOOLEAN,revision BIGINT);
CREATE TABLE WEAVER_WORKSPACE_MEDIA(user_id CHAR(36) CHARACTER SET ascii,byte_size BIGINT);
